package checks;
import dev.zomboid.mutants.horror.*;import java.util.*;import net.neoforged.neoforge.registries.DeferredRegister;import net.neoforged.neoforge.common.DeferredSpawnEggItem;import net.minecraft.world.entity.monster.Zombie;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.entity.player.Player;
public class HorrorChecks{
 static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}public static class Bus implements net.neoforged.bus.api.IEventBus{}public static class Part{public float xRot,yRot,zRot;}public static class Model{public Part head=new Part(),body=new Part(),rightArm=new Part(),leftArm=new Part(),rightLeg=new Part(),leftLeg=new Part();private Part jaw=new Part();}
 public static void main(String[]args)throws Exception{Horror.register(new Bus());DeferredRegister items=(DeferredRegister)Horror.items,sounds=(DeferredRegister)Horror.sounds;ok(items.registered&&sounds.registered,"both deferred registries attached to mod bus");ok(items.entries.containsKey("screamer_spawn_egg"),"egg registered exact id");DeferredSpawnEggItem egg=(DeferredSpawnEggItem)((DeferredRegister.Holder)Horror.egg).get();ok(egg.type.get()instanceof net.minecraft.world.entity.EntityType,"egg points to screamer entity supplier");ok(egg.background!=egg.highlight,"egg has contrasting colors");
  var event=new net.neoforged.neoforge.event.BuildCreativeModeTabContentsEvent(net.minecraft.world.item.CreativeModeTabs.SPAWN_EGGS);var handler=Class.forName("dev.zomboid.mutants.horror.CreativeEgg");ok(handler.getAnnotation(net.neoforged.fml.common.EventBusSubscriber.class).bus()==net.neoforged.fml.common.EventBusSubscriber.Bus.MOD,"creative handler on mod bus");handler.getMethod("contents",event.getClass()).invoke(null,event);ok(event.items.size()==1&&event.items.get(0)instanceof DeferredSpawnEggItem,"egg visible in creative spawn eggs");var other=new net.neoforged.neoforge.event.BuildCreativeModeTabContentsEvent(new Object());Horror.creative(other);ok(other.items.isEmpty(),"egg not injected into every tab");
  ServerLevel level=new ServerLevel();Player player=new Player(level);player.x=20;level.players.add(player);Class<?>type=Class.forName("dev.zomboid.mutants.Screamers$Screamer");Zombie entity=(Zombie)type.getConstructor(net.minecraft.world.entity.EntityType.class,net.minecraft.world.level.Level.class).newInstance(new net.minecraft.world.entity.EntityType(),level);
  entity.tick();ok(entity.getTarget()==player&&entity.plays==1,"real patched tick detects player and cries immediately");ok(entity.sound.id().id().equals("mutants_l4d2:screamer_detect")&&entity.pitch==1&&entity.volume==6,"registered user audio at intended pitch and range");ok(dev.zomboid.mutants.HordeScent.calls==1&&dev.zomboid.mutants.HordeScent.target==player&&dev.zomboid.mutants.HordeScent.radius==96,"real tick invokes existing horde attraction once");ok(entity.nav.speed==1.35,"real path pursuit is faster");ok(level.broadcasts==1&&level.lastEvent==61,"cry synchronized through entity event");for(int i=1;i<240;i++){level.time=i;entity.tick();}ok(entity.plays==1,"10 second clip does not restart every 4 seconds");level.time=240;entity.tick();ok(entity.plays==2,"cry repeats after twelve seconds");Player next=new Player(level);next.x=21;entity.setTarget(next);level.time=241;entity.tick();ok(entity.plays==3,"different detected target gets immediate cry");ok(!(Boolean)type.getMethod("doHurtTarget",net.minecraft.world.entity.Entity.class).invoke(entity,player),"screamer remains support mob without melee damage");
  entity.handleEntityEvent((byte)61);ok(Horror.screaming(entity),"client event activates scream pose");Model model=new Model();Horror.animate(model,entity,1,.8f,1);ok(model.jaw.xRot>.9&&Math.abs(model.leftArm.xRot-model.rightArm.xRot)>.1,"wide jaw and asymmetric arms while screaming");entity.tickCount+=202;ok(!Horror.screaming(entity),"scream pose ends with clip");entity.handleEntityEvent((byte)99);ok(entity.lastEvent==99,"other vanilla entity events forwarded to parent");
  for(int i=0;i<1500;i++){Horror.animate(model,entity,i*.2f,.7f,i*.15f);for(Part p:List.of(model.body,model.leftArm,model.rightArm,model.leftLeg,model.rightLeg,model.jaw)){ok(Float.isFinite(p.xRot)&&Float.isFinite(p.yRot)&&Float.isFinite(p.zRot),"finite pose");ok(Math.abs(p.xRot)<3.2&&Math.abs(p.yRot)<3.2&&Math.abs(p.zRot)<3.2,"no accumulating rotation or broken bounds");}}
  System.out.println("HORROR_CHECKS="+checks);
 }
}
